+import http from "http";
+import { getNextJob, markJobConsumed } from "./external-consumer.ts";
+
+const API_KEY = process.env.EXTERNAL_API_KEY || "default-key";
+
+export const createServer = (): http.Server => {
+  return http.createServer(async (req, res) => {
+    const auth = req.headers.authorization;
+    if (auth !== `Bearer ${API_KEY}`) {
+      res.writeHead(401, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Unauthorized" }));
+      return;
+    }
+
+    if (req.method === "GET" && req.url === "/jobs/next") {
+      try {
+        const job = await getNextJob();
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify(job || {}));
+      } catch (err) {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: String(err) }));
+      }
+      return;
+    }
+
+    if (req.method === "POST" && req.url?.startsWith("/jobs/")) {
+      const jobId = req.url.split("/")[2];
+      if (req.url.endsWith("/consumed")) {
+        try {
+          await markJobConsumed(jobId);
+          res.writeHead(200, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ status: "ok" }));
+        } catch (err) {
+          res.writeHead(500, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ error: String(err) }));
+        }
+        return;
+      }
+    }
+
+    res.writeHead(404, { "Content-Type": "application/json" });
+    res.end(JSON.stringify({ error: "Not found" }));
+  });
+};
+
+export const startServer = (port: number = 3000): void => {
+  const server = createServer();
+  server.listen(port, () => {
+    console.log(`External job API listening on port ${port}`);
+  });
+};
