+// Example: How the external notifications service would consume jobs
+
+interface Job {
+  id: string;
+  payload: string;
+}
+
+class NotificationsServiceClient {
+  private baseUrl: string;
+  private apiKey: string;
+  private pollIntervalMs: number;
+
+  constructor(baseUrl: string, apiKey: string, pollIntervalMs = 1000) {
+    this.baseUrl = baseUrl;
+    this.apiKey = apiKey;
+    this.pollIntervalMs = pollIntervalMs;
+  }
+
+  private async request(method: string, path: string, body?: unknown): Promise<unknown> {
+    const response = await fetch(`${this.baseUrl}${path}`, {
+      method,
+      headers: {
+        "Authorization": `Bearer ${this.apiKey}`,
+        "Content-Type": "application/json",
+      },
+      body: body ? JSON.stringify(body) : undefined,
+    });
+    if (!response.ok) {
+      throw new Error(`API request failed: ${response.status} ${response.statusText}`);
+    }
+    return response.json();
+  }
+
+  async getNextJob(): Promise<Job | null> {
+    const result = await this.request("GET", "/jobs/next");
+    if (!result || typeof result !== "object" || !("id" in result)) {
+      return null;
+    }
+    return result as Job;
+  }
+
+  async markJobConsumed(jobId: string): Promise<void> {
+    await this.request("POST", `/jobs/${jobId}/consumed`);
+  }
+
+  async startConsuming(handler: (payload: string) => Promise<void>): Promise<void> {
+    for (;;) {
+      const job = await this.getNextJob();
+      if (job === null) {
+        await new Promise((resolve) => setTimeout(resolve, this.pollIntervalMs));
+        continue;
+      }
+      try {
+        await handler(job.payload);
+        await this.markJobConsumed(job.id);
+      } catch (err) {
+        console.error(`Failed to process job ${job.id}:`, err);
+      }
+    }
+  }
+}
+
+// Usage in external notifications service:
+// const client = new NotificationsServiceClient(
+//   process.env.JOBS_API_URL || "http://localhost:3000",
+//   process.env.JOBS_API_KEY || "your-api-key"
+// );
+//
+// client.startConsuming(async (payload) => {
+//   const notification = JSON.parse(payload);
+//   await sendNotification(notification);
+// });
