+import { pool } from "./pool.ts";
+
+export interface ExternalJob {
+  id: string;
+  payload: string;
+}
+
+// For services that poll via HTTP API
+export const getNextJob = async (): Promise<ExternalJob | null> => {
+  const result = await pool.query(
+    "SELECT id, payload FROM jobs WHERE status = 'ready' ORDER BY created_at LIMIT 1 FOR UPDATE",
+  );
+  const row = result.rows[0];
+  if (row === undefined) return null;
+  await pool.query("UPDATE jobs SET status = 'claimed' WHERE id = $1", [row.id]);
+  return { id: row.id, payload: row.payload };
+};
+
+// For services that consume via message queue
+const jobQueue: ExternalJob[] = [];
+let isPublishing = false;
+
+export const startPublishingJobs = async (): Promise<void> => {
+  isPublishing = true;
+  for (;;) {
+    const job = await pool.query(
+      "SELECT id, payload FROM jobs WHERE status = 'ready' ORDER BY created_at LIMIT 1 FOR UPDATE",
+    );
+    const row = job.rows[0];
+    if (row === undefined) {
+      await new Promise((resolve) => setTimeout(resolve, 1000));
+      continue;
+    }
+    jobQueue.push({ id: row.id, payload: row.payload });
+    await pool.query("UPDATE jobs SET status = 'published' WHERE id = $1", [row.id]);
+  }
+};
+
+export const getPublishedJob = (): ExternalJob | null => {
+  return jobQueue.shift() || null;
+};
+
+export const markJobConsumed = async (jobId: string): Promise<void> => {
+  await pool.query("UPDATE jobs SET status = 'consumed' WHERE id = $1", [jobId]);
+};
