+-- Jobs table with status tracking for both internal and external consumers
+CREATE TABLE IF NOT EXISTS jobs (
+  id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
+  payload TEXT NOT NULL,
+  status TEXT DEFAULT 'ready',
+  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
+  CONSTRAINT status_check CHECK (status IN ('ready', 'claimed', 'published', 'consumed', 'failed'))
+);
+
+-- Status meanings:
+-- ready: Job is waiting to be claimed by either internal worker or external consumer
+-- claimed: Internal worker has claimed this job
+-- published: External consumer has claimed this job
+-- consumed: External consumer has finished processing
+-- failed: Job processing failed
+
+CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON jobs(status, created_at) WHERE status = 'ready';
